/**
 * Writes the GraphQL contract (src/graphql/schema/*.graphql) into a TypeScript module, for runtimes that cannot
 * read files at startup (the Cloudflare Worker). Run after changing a .graphql file:
 * `pnpm --filter @bambino/api schema:bundle`. A test fails while the generated file is out of date.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { loadTypeDefs } from '../graphql/load-schema';

const target = fileURLToPath(new URL('../graphql/schema-sdl.generated.ts', import.meta.url));
writeFileSync(
  target,
  `// Generated by \`pnpm --filter @bambino/api schema:bundle\` from src/graphql/schema/*.graphql. Do not edit.\nexport const SCHEMA_SDL = ${JSON.stringify(loadTypeDefs())};\n`,
);
console.log(`Wrote ${target}`);
